const courseDomains=[{id:'A',name:'Sciences infirmières et raisonnement clinique',ues:[['A.1','Fondements des sciences infirmières et raisonnement clinique'],['A.2','Législation, déontologie, éthique']]},{id:'B',name:'Pratiques cliniques infirmières, qualité et gestion des risques',ues:[['B.1','Sciences biomédicales'],['B.2','Sciences humaines et sociales'],['B.3','Pratiques et interventions infirmières'],['B.4','Démarche qualité et gestion des risques']]},{id:'C',name:'Prévention et promotion de la santé',ues:[['C.1','Santé publique, promotion de la santé et prévention, éducation thérapeutique'],['C.2','Santé environnementale et transition écologique']]},{id:'D',name:'Communication, travail en équipe et leadership',ues:[['D.1','Savoir-être, communication professionnelle et leadership'],['D.2','Coordination des activités et des soins et gestion d’une structure'],['D.3','Formation, développement des compétences et analyse des pratiques professionnelles'],['D.4','Numérique en santé']]},{id:'E',name:'Démarche scientifique, initiation à la recherche et méthodologie',ues:[['E.1','Recherche, méthodes, analyse critique et données probantes'],['E.2','Langue vivante étrangère'],['E.3','Méthodes de travail et aide à la réussite']]}];
let courseDomain=null,courseUE=null,revisionId=null,courseReadId=null,evaluationId=null;
let practiceDomain=null,practiceUE=null;
const courseQuizState=new Map();
const savedSessions=new Map();
const reviewSchedule=new Map();
let pendingBackup=null;
try{const data=JSON.parse(localStorage.getItem('ifsi-review-v1')||'[]');if(Array.isArray(data))for(const [id,value] of data)if(value&&typeof value.due==='string')reviewSchedule.set(id,value)}catch{}
try{const data=JSON.parse(localStorage.getItem('ifsi-sessions-v1')||'[]');if(Array.isArray(data))for(const [key,value] of data)if(typeof key==='string'&&value&&Array.isArray(value.ids))savedSessions.set(key,value)}catch{}
try{const data=JSON.parse(localStorage.getItem('ifsi-course-qcm-v1')||'[]');if(Array.isArray(data))for(const [key,value] of data)if(typeof key==='string'&&value&&Array.isArray(value.selected))courseQuizState.set(key,value)}catch{}
function saveCourseQuiz(){try{localStorage.setItem('ifsi-course-qcm-v1',JSON.stringify([...courseQuizState]))}catch{storageAvailable=false;updateStorageStatus()}}
function saveSession(){if(!session?.key)return;session.updatedAt=Date.now();const {key,qs,...state}=session;savedSessions.set(key,{...state,ids:qs.map(q=>q.id)});try{localStorage.setItem('ifsi-sessions-v1',JSON.stringify([...savedSessions]))}catch{storageAvailable=false;updateStorageStatus()}}
function restartSession(){if(!session)return;session.index=0;session.selected=[];session.graded=false;session.score=0;session.resume=false;quiz();window.scrollTo(0,0)}
let courseSemester=1;
try{const saved=Number(localStorage.getItem('ifsi-semester'));if(Number.isInteger(saved)&&saved>=1&&saved<=6)courseSemester=saved}catch{}


const content=document.getElementById('content');let page='home',session=null;const records=new Map();const letters=['A','B','C','D','E'];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Keep existing question IDs and add course QCM that have no training theme yet.
for(const c of courseFiles){if(themes.some(t=>t.courseId===c.id))continue;themes.push({title:c.title,courseId:c.id,ue:c.ue,semester:c.semester,questions:courseQuizBank[c.id].map((q,i)=>({...q,id:200000+courseFiles.indexOf(c)*100+i,answers:q.answers.map(n=>letters[n])}))})}
function trainingMeta(t){const c=courseFiles.find(c=>c.id===t.courseId);return {ue:t.ue||c?.ue||'B.1',semester:t.semester||c?.semester||1}}
function trainingThemes(ue){return themes.map((t,i)=>({t,i,...trainingMeta(t)})).filter(t=>t.semester===courseSemester&&(!ue||t.ue===ue))}
function trainingCount(ue){return trainingThemes(ue).reduce((n,{t})=>n+t.questions.length,0)}
const all=themes.flatMap((t,ti)=>t.questions.map(q=>({...q,theme:t.title,ti})));const errors=()=>all.filter(q=>records.has(q.id)&&!records.get(q.id).correct);const correct=()=>[...records.values()].filter(r=>r.correct).length;
const STORAGE_KEY='ifsi-progress-v1';
let storageAvailable=true;
const drafts=new Map();
const customThemes=new Set();
try{const ids=JSON.parse(localStorage.getItem('ifsi-custom-themes-v1')||'[]');if(Array.isArray(ids))for(const id of ids){const i=themes.findIndex(t=>t.questions[0]?.id===id);if(i>=0)customThemes.add(i)}}catch{}
let customSelectionOpen=false;
function restoreProgress(){
 try{const raw=localStorage.getItem(STORAGE_KEY);if(!raw)return;const data=JSON.parse(raw);if(data.version!==1||!Array.isArray(data.records))return;const ids=new Set(all.map(q=>q.id));for(const entry of data.records){if(Array.isArray(entry)&&ids.has(entry[0])&&typeof entry[1]?.correct==='boolean')records.set(entry[0],{...entry[1],correct:entry[1].correct})}if(Array.isArray(data.drafts))for(const entry of data.drafts){if(Array.isArray(entry)&&ids.has(entry[0])&&Array.isArray(entry[1])&&!records.has(entry[0]))drafts.set(entry[0],entry[1].filter(v=>letters.includes(v)))}}
 catch{storageAvailable=false}
}
function saveProgress(){
 try{localStorage.setItem(STORAGE_KEY,JSON.stringify({version:1,records:[...records],drafts:[...drafts],updatedAt:new Date().toISOString()}));storageAvailable=true}
 catch{storageAvailable=false}
 updateStorageStatus();
}
function updateStorageStatus(){const el=document.getElementById('storage-status');if(el)el.textContent=storageAvailable?'Progression enregistrée sur cet appareil, dans ce navigateur.':'Sauvegarde indisponible dans ce navigateur : les résultats restent uniquement pendant cette ouverture.'}
restoreProgress();
mergeCourseProgress();

function navigate(p){practiceDomain=null;practiceUE=null;evaluationId=null;courseDomain=null;courseUE=null;revisionId=null;courseReadId=null;customSelectionOpen=false;page=p;session=null;render();window.scrollTo(0,0)}
function render(){document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false')});if(session){quiz();return}if(page==='home'){renderDashboard()}
else if(page==='progress'){renderProgress()}
else if(page==='backup'){renderBackup()}
else if(page==='atlas'){renderAtlas()}
else if(page==='courses'){renderCourses()}
else if(page==='evaluations'){renderEvaluations()}
else if(page==='practice'){renderPractice()}
else{const qs=errors();content.innerHTML=`<p class="muted">MES ERREURS</p><h1>Comprendre pour progresser.</h1><p class="muted">Les questions incorrectes sont conservées ici. Une bonne réponse lors d’un nouvel essai les retire du carnet.</p>${qs.length?`<div class="card row"><strong>${qs.length} question${qs.length>1?'s':''} à retravailler</strong><button class="primary" data-retry="all">Rejouer mes erreurs</button></div><div class="errorlist">${qs.map(q=>`<article class="card"><span class="tag">${esc(q.theme)}</span><h3 class="error-title">${esc(q.text)}</h3><p><strong>Bonnes réponses : ${q.answers.join(', ')}</strong></p><p class="muted">${esc(q.explanation)}</p><button data-retry="${q.id}">Réessayer cette question</button></article>`).join('')}</div>`:`<div class="card empty"><h2>Ton carnet est prêt.</h2><p class="muted">Réponds à quelques QCM pour retrouver ici les notions à retravailler.</p><button class="primary" data-page="practice">Commencer un entraînement</button></div>`}`}}
function semesterPicker(){return `<div class="semester-picker"><label for="course-semester">Mon semestre</label><select id="course-semester">${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${n===courseSemester?'selected':''}>Semestre ${n} · ${Math.ceil(n/2)}${n<=2?'re':'e'} année</option>`).join('')}</select></div>`}
function coursesFor(ue){return courseFiles.filter(c=>c.semester===courseSemester&&(!ue||c.ue===ue))}
function courseCount(ue){const n=coursesFor(ue).length;return n?`${n} cours · ${n} fiches de révision`:'Aucun cours ajouté'}
function courseReferences(id){const refs=courseSources[id]||[];return refs.length?`<section class="card"><h2>Repères pour approfondir</h2><ul>${refs.map(r=>`<li><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)}</a></li>`).join('')}</ul></section>`:''}
function renderStudyVisuals(id){const visuals=ownCourses[id]?.visuals||[];return visuals.map(v=>`<section class="card study-visual"><p class="visual-kicker">COMPRENDRE EN UN REGARD</p><h2>${esc(v.title)}</h2>${v.columns?`<div class="study-table-wrap" tabindex="0" role="region" aria-label="${esc(v.title)}"><table class="study-table"><thead><tr>${v.columns.map(x=>`<th scope="col">${esc(x)}</th>`).join('')}</tr></thead><tbody>${v.rows.map(row=>`<tr>${row.map((x,i)=>i===0?`<th scope="row">${esc(x)}</th>`:`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<ol class="study-flow">${v.steps.map(([h,t],i)=>`<li><span class="flow-number">${i+1}</span><div><strong>${esc(h)}</strong><p>${esc(t)}</p></div></li>`).join('')}</ol>`}${v.note?`<p class="note">${esc(v.note)}</p>`:''}</section>`).join('')}
function renderOwnCourse(c){const lesson=ownCourses[c.id],isProgram=Boolean(c.syllabus);return `<button class="back" data-ue="${c.ue}">← Retour à l’UE ${c.ue}</button><header class="lesson-hero"><p class="visual-kicker">SEMESTRE ${c.semester} · UE ${c.ue}${c.syllabus?' · '+c.syllabus:''}</p><h1>${esc(c.title)}</h1>${isProgram?`<div class="lesson-meta"><span>Chapitre ${c.order} / 8</span><span>≈ ${c.readingMinutes} min de lecture</span><span>${courseQuizBank[c.id].length} QCM corrigés</span></div>`:''}<p class="muted">${esc(lesson.intro)}</p><button class="primary" data-revision="${c.id}">Fiche et QCM →</button></header><article class="revision-sheet lesson-reader">${renderCourseGallery(c.id)}${renderCourseInteractive(c.id)}${isProgram?`<details class="card study-toc" open><summary>Dans ce cours</summary><ol>${lesson.sections.map(([h],i)=>`<li><a href="#lesson-${c.id}-${i}">${esc(h.replace(/^\d+ · /,''))}</a></li>`).join('')}<li><a href="#essentiel-${c.id}">L’essentiel à mémoriser</a></li></ol></details>`:''}${lesson.sections.map(([title,paragraphs],index)=>`<section class="card lesson-section" id="lesson-${c.id}-${index}"><h2>${esc(title)}</h2>${paragraphs.map(t=>`<p>${esc(t)}</p>`).join('')}</section>${index===0?isProgram?renderStudyVisuals(c.id):courseVisual(c.id):''}`).join('')}<section class="card essentials-card" id="essentiel-${c.id}"><p class="visual-kicker">À MÉMORISER</p><h2>L’essentiel</h2><ul>${lesson.takeaways.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><button class="primary" data-revision="${c.id}">Passer à la fiche et aux QCM</button></section>${courseReferences(c.id)}<p class="note">Cours original pour cet espace. Les exemples sont pédagogiques ; les procédures de soins relèvent de la formation et des protocoles applicables.</p></article>`}
function renderCourseQCM(c){const qs=courseQuizBank[c.id]||[];let done=0,score=0;for(let i=0;i<qs.length;i++){const st=courseQuizState.get(c.id+'-'+i);if(st?.graded){done++;if(st.correct)score++}}return `<section class="card"><div class="row"><h2>QCM corrigés</h2><button data-course-reset="${c.id}">Recommencer</button></div><p>Chaque question comporte cinq propositions et une ou plusieurs bonnes réponses. Coche toutes les bonnes réponses, puis valide.</p><p role="status">${done} / ${qs.length} corrigés · ${score} / ${done} réussis</p><p class="note">Une question est réussie si toutes les bonnes réponses, et elles seules, sont sélectionnées. Tes réponses sont sauvegardées sur cet appareil, même après fermeture du site.</p><a class="course-link" href="#course-question-${c.id}-${Math.max(0,qs.findIndex((_,i)=>!courseQuizState.get(c.id+'-'+i)?.graded))}">Reprendre mes QCM →</a></section>${qs.map((q,i)=>{const key=c.id+'-'+i,st=courseQuizState.get(key)||{selected:[]};return `<section id="course-question-${c.id}-${i}" class="card course-question-card"><fieldset class="course-qcm"><legend>${i+1}. ${esc(q.text)}</legend>${q.options.map((o,j)=>`<label class="option ${st.graded&&q.answers.includes(j)?'good':st.graded&&st.selected.includes(j)?'bad':''}"><input type="checkbox" data-course-choice="${key}" value="${j}" ${st.selected.includes(j)?'checked':''} ${st.graded?'disabled':''}><span><strong>${letters[j]}.</strong> ${esc(o)}${st.graded&&q.answers.includes(j)?'<span class="status">Bonne réponse</span>':''}${st.graded&&st.selected.includes(j)&&!q.answers.includes(j)?'<span class="status">Réponse incorrecte</span>':''}</span></label>`).join('')}</fieldset>${st.graded?`<div class="result ${st.correct?'good':'bad'}" role="status"><strong>${st.correct?'Réponse juste':'À revoir'} · Bonnes réponses : ${q.answers.map(n=>letters[n]).join(', ')}</strong><p>${esc(q.explanation)}</p>${renderAnswerReview(q,st.selected.map(n=>letters[n]))}</div>`:`<button class="primary" data-course-validate="${c.id}" data-course-question="${i}">Valider la réponse</button>${st.error?'<p role="alert">Coche au moins une proposition.</p>':''}`}</section>`}).join('')}<button data-course-reset="${c.id}">Recommencer ces QCM</button>`}
function renderRevision(c){const sheet=revisionSheets[c.id];return `<button class="back" data-ue="${c.ue}">← Retour à l’UE ${c.ue}</button><header class="lesson-hero"><p class="visual-kicker">SEMESTRE ${c.semester} · UE ${c.ue} · FICHE DE RÉVISION</p><h1>${esc(c.title)}</h1><p class="muted">${esc(sheet.intro)}</p><div class="course-actions"><button data-read-course="${c.id}">Lire le cours</button><a class="course-link" href="#recall-${c.id}">Questions ouvertes</a><a class="course-link" href="#qcm-${c.id}">${courseQuizBank[c.id].length} QCM corrigés</a></div></header><article class="revision-sheet lesson-reader">${renderCourseGallery(c.id)}${sheet.sections.map(([title,points],i)=>`<section class="card ${i===0?'essentials-card':''}"><h2>${esc(title)}</h2><ul>${points.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section>`).join('')}<section class="card pitfalls-card"><p class="visual-kicker">VIGILANCE</p><h2>Les pièges à éviter</h2><ul>${sheet.pitfalls.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section><section class="card" id="recall-${c.id}"><h2>Questions ouvertes</h2><p class="note">Réponds de tête, puis ouvre la réponse.</p>${sheet.questions.map(([q,a])=>`<details class="recall"><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</section><div id="qcm-${c.id}" class="study-anchor"></div>${renderCourseQCM(c)}</article>`}
function courseCard(c){return `<article class="card course-card ${c.syllabus?'program-card':''}">${c.syllabus?`<span class="chapter-number">${String(c.order).padStart(2,'0')}</span>`:''}<span class="badge">Semestre ${c.semester} · ${c.syllabus||'UE '+c.ue}</span><h2>${esc(c.title)}</h2>${c.description?`<p class="note">${esc(c.description)}</p>`:''}<p class="course-card-meta">${c.readingMinutes?'≈ '+c.readingMinutes+' min de lecture · ':''}${courseQuizBank[c.id].length} QCM corrigés</p><div class="course-actions"><button data-read-course="${c.id}">Lire le cours</button><button class="primary" data-revision="${c.id}">Réviser</button></div></article>`}
function renderCourseLibrary(ue){const cs=coursesFor(ue),program=cs.filter(c=>c.syllabus),other=cs.filter(c=>!c.syllabus);return `${program.length?`<section class="program-header"><p class="visual-kicker">TON PROGRAMME À RÉVISER · B.1.a</p><h2>Les bases du vivant et de l’hygiène</h2><p>Huit thèmes, des cours à lire à ton rythme et des corrections pour comprendre tes réponses.</p><div class="lesson-meta"><span>${program.length} cours</span><span>${program.reduce((n,c)=>n+courseQuizBank[c.id].length,0)} QCM</span><span>Fiches et questions ouvertes</span></div></section><div class="program-grid">${program.sort((a,b)=>a.order-b.order).map(courseCard).join('')}</div>`:''}${other.length?`${program.length?'<h2 class="other-courses-title">Tes autres cours de B.1</h2>':''}<div class="course-list">${other.map(courseCard).join('')}</div>`:''}`}
function renderCourses(){
 if(courseReadId){const c=coursesFor(courseUE).find(c=>c.id===courseReadId);if(c){content.innerHTML=semesterPicker()+renderOwnCourse(c);return}courseReadId=null}
 if(revisionId){const c=coursesFor(courseUE).find(c=>c.id===revisionId);if(c){content.innerHTML=semesterPicker()+renderRevision(c);return}revisionId=null}

 const source='<p class="note">Référentiel 2026 · <a href="https://www.legifrance.gouv.fr/loda/article_lc/LEGIARTI000053570499" target="_blank" rel="noopener">Référentiel officiel</a></p>';
 if(courseUE){const d=courseDomains.find(d=>d.id===courseDomain),u=d.ues.find(u=>u[0]===courseUE);content.innerHTML=`${semesterPicker()}<button class="back" data-domain="${d.id}">← Domaine ${d.id}</button><p class="muted">Mes cours / Semestre ${courseSemester} / Domaine ${d.id} / UE ${u[0]}</p><h1>${esc(u[1])}</h1>${coursesFor(courseUE).length?`<p class="muted">${courseCount(courseUE)}. Retrouve les cours, les fiches et les QCM corrigés.</p>${renderCourseLibrary(courseUE)}`:`<section class="card empty" style="margin-top:24px"><h2>Aucun cours ajouté pour le moment</h2><p class="muted">Les cours de cette UE pour le semestre ${courseSemester} apparaîtront ici lorsqu’ils seront ajoutés.</p></section>`}${source}`;return}
 if(courseDomain){const d=courseDomains.find(d=>d.id===courseDomain);content.innerHTML=`${semesterPicker()}<button class="back" data-page="courses">← Tous les domaines</button><p class="muted">SEMESTRE ${courseSemester} · DOMAINE ${d.id}</p><h1>${esc(d.name)}</h1><div class="themegrid">${d.ues.map(([code,title])=>`<button class="theme" data-ue="${code}"><span><span class="badge">UE ${code}</span><b style="display:block;margin-top:12px">${esc(title)}</b><small>${courseCount(code)}</small></span><span aria-hidden="true">→</span></button>`).join('')}</div>${['C','D','E'].includes(d.id)?'<p class="note" style="margin-top:20px">Le domaine comprend également une UE libre, selon l’offre de formation de ton établissement.</p>':''}${source}`;return}
 content.innerHTML=`${semesterPicker()}<p class="muted">MES COURS · SEMESTRE ${courseSemester} · RÉFÉRENTIEL 2026</p><h1>Tes cours, bien organisés.</h1><p class="muted">Choisis ton semestre, un domaine, puis une unité d’enseignement.</p><div class="themegrid">${courseDomains.map(d=>`<button class="theme" data-domain="${d.id}"><span><span class="badge">Domaine ${d.id}</span><b style="display:block;margin-top:12px">${esc(d.name)}</b><small>${d.ues.length} UE · ${coursesFor().filter(c=>c.ue.startsWith(d.id+'.')).length} cours</small></span><span aria-hidden="true">→</span></button>`).join('')}</div>${source}`;
}
function renderPractice(){
 const top=semesterPicker()+`<p class="visual-kicker">ENTRAÎNEMENT · SEMESTRE ${courseSemester}</p>`;
 const custom=`<section class="card row"><div><h2>Entraînement personnalisé</h2><p class="muted">Mélange les QCM de plusieurs UE ou chapitres. À refaire autant de fois que tu veux.</p></div><button class="primary" id="custom-open">Créer mon entraînement</button></section>`;
 if(practiceUE){const d=courseDomains.find(d=>d.id===practiceDomain),u=d.ues.find(u=>u[0]===practiceUE),list=trainingThemes(practiceUE);content.innerHTML=top+`<button class="back" data-practice-domain="${d.id}">← Domaine ${d.id}</button><p class="muted">Domaine ${d.id} / UE ${u[0]}</p><h1>${esc(u[1])}</h1><p class="muted">${trainingCount(practiceUE)} QCM corrigés. Choisis un chapitre pour commencer ou reprendre.</p>${list.length?`<div class="themegrid">${list.map(({t,i})=>{const done=t.questions.filter(q=>records.has(q.id)).length;return `<article class="card course-card"><h2>${esc(t.title)}</h2><p class="note">${t.questions.length} QCM · ${done} travaillés</p><div class="course-actions"><button class="primary" data-theme="${i}">Commencer / Reprendre</button><button data-theme-restart="${i}">Recommencer</button></div></article>`}).join('')}</div>`:'<section class="card empty"><h2>Aucun QCM pour le moment</h2><p>Les entraînements de cette UE apparaîtront ici lorsqu’ils seront ajoutés.</p></section>'}`;return}
 if(practiceDomain){const d=courseDomains.find(d=>d.id===practiceDomain);content.innerHTML=top+`<button class="back" data-page="practice">← Tous les domaines</button><span class="badge">Domaine ${d.id}</span><h1>${esc(d.name)}</h1><div class="themegrid">${d.ues.map(([code,title])=>`<button class="theme" data-practice-ue="${code}"><span><span class="badge">UE ${code}</span><b style="display:block;margin-top:12px">${esc(title)}</b><small>${trainingCount(code)} QCM corrigés</small></span><span aria-hidden="true">→</span></button>`).join('')}</div>`;return}
 content.innerHTML=top+`<h1>Que veux-tu réviser ?</h1><p class="muted">Choisis un domaine, puis une UE pour retrouver tes QCM corrigés.</p>${custom}<div class="themegrid">${courseDomains.map(d=>`<button class="theme" data-practice-domain="${d.id}"><span><span class="badge">Domaine ${d.id}</span><b style="display:block;margin-top:12px">${esc(d.name)}</b><small>${d.ues.length} UE · ${d.ues.reduce((n,[code])=>n+trainingCount(code),0)} QCM</small></span><span aria-hidden="true">→</span></button>`).join('')}</div>`;
}
function themeCards(short){return `<div class="themegrid">${themes.map((t,i)=>{const done=t.questions.filter(q=>records.has(q.id)).length;return `<button class="theme" data-theme="${i}"><span><b>${esc(t.title)}</b><small>${t.description?esc(t.description)+'<br>':''}${t.questions.length} QCM · ${done} travaillé${done>1?'s':''}${done===t.questions.length?' · Terminé':done?' · Reprendre':''}</small></span><span aria-hidden="true">→</span></button>`}).filter((_,i)=>!short||i<4).join('')}</div>${short?'<p style="margin-top:15px"><button data-page="practice">Voir tous les thèmes</button></p>':''}`}
function customPicker(){
 customSelectionOpen=true;
 content.innerHTML=`<button class="back" data-page="practice">← Les entraînements</button><h1>Ton entraînement, tes thèmes.</h1><p class="muted">Sélectionne un ou plusieurs thèmes. Les questions sont mélangées au premier lancement, puis ta séance est sauvegardée pour la reprendre.</p><section class="card"><div class="row"><h2>Choisir les thèmes</h2><button id="custom-toggle">${trainingThemes().length&&trainingThemes().every(({i})=>customThemes.has(i))?'Tout désélectionner':'Tout sélectionner'}</button></div>${courseDomains.map(d=>d.ues.map(([code,title])=>{const list=trainingThemes(code);return list.length?`<details class="recall" open><summary>UE ${code} · ${esc(title)}</summary>${list.map(({t,i})=>`<label class="option"><input type="checkbox" data-custom-theme="${i}" ${customThemes.has(i)?'checked':''}><span><b>${esc(t.title)}</b><br><span class="note">${t.questions.length} QCM</span></span></label>`).join('')}</details>`:''}).join('')).join('')}<p id="custom-count" aria-live="polite"></p><button class="primary" id="custom-start">Commencer / Reprendre</button> <button id="custom-restart">Recommencer</button><div id="custom-alert" role="alert"></div></section>`;
 customCount();
}
function customCount(){const n=all.filter(q=>customThemes.has(q.ti)).length;document.getElementById('custom-count').textContent=`${customThemes.size} thème${customThemes.size>1?'s':''} · ${n} question${n>1?'s':''}`}
function customStart(){
 const qs=all.filter(q=>customThemes.has(q.ti));
 if(!qs.length){document.getElementById('custom-alert').textContent='Choisis au moins un thème pour commencer.';return}
 for(let i=qs.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[qs[i],qs[j]]=[qs[j],qs[i]]}
 try{localStorage.setItem('ifsi-custom-themes-v1',JSON.stringify([...customThemes].map(i=>themes[i].questions[0]?.id)))}catch{}customSelectionOpen=false;start(qs,'Entraînement personnalisé',false,'custom');session.custom=true;quiz();
}
function start(qs,title,resume=false,context='practice'){
 page='practice';const key=context+':'+qs.map(q=>q.id).sort((a,b)=>a-b).join(',');const saved=savedSessions.get(key),byId=new Map(qs.map(q=>[q.id,q]));
 if(saved&&saved.ids.length===qs.length&&saved.ids.every(id=>byId.has(id))&&Number.isInteger(saved.index)&&saved.index>=0&&saved.index<=qs.length){session={...saved,key,qs:saved.ids.map(id=>byId.get(id)),selected:Array.isArray(saved.selected)?saved.selected.filter(a=>letters.includes(a)):[],resume:false};}
 else{const pending=resume?qs.findIndex(q=>!records.has(q.id)):0,index=pending===-1?qs.length:pending;session={key,qs,title,index,selected:resume&&index<qs.length?[...(drafts.get(qs[index].id)||[])]:[],graded:false,score:resume?qs.filter(q=>records.get(q.id)?.correct).length:0,resume:false};}
 render();window.scrollTo(0,0)
}
function trainingOverview(){if(!session||session.custom)return '';const linked=themes[session.qs[0]?.ti]?.courseId;const t=themes[session.qs[0]?.ti];if(!t?.overview)return '';return `<details class="card"><summary><strong>Les repères à connaître · IFSI 1re année</strong></summary>${linked?`<p><button data-training-course="${esc(linked)}">Lire le cours complet</button></p>`:''}<p>Ces repères aident à démarrer. Lis le cours associé pour retrouver les explications et les exemples.</p><div class="conversion-grid">${t.overview.map(([title,text])=>`<div><strong>${esc(title)}</strong><p>${esc(text)}</p></div>`).join('')}</div><p class="note">${t.references.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)}</a>`).join(' · ')}</p></details>`}
function quiz(){saveSession();const s=session;const returnButton=s.evaluation?`<button class="back" data-evaluation-open="${s.evaluation}">← Évaluation du 14/10</button>`:'<button class="back" data-page="practice">← Les entraînements</button>';const endReturn=`<button class="primary" id="session-restart">Recommencer ces QCM</button>${s.evaluation?` <button data-evaluation-open="${s.evaluation}">Retour à l’évaluation</button>`:''}`;if(s.index===s.qs.length){content.innerHTML=`${returnButton}<div class="card empty"><span class="badge">Séance terminée</span><h1 style="margin-top:20px">${s.score} / ${s.qs.length}</h1><p>${esc(s.title)}</p><p class="muted">Une question est réussie si toutes les bonnes réponses sont cochées, sans réponse fausse.</p>${endReturn}${s.custom&&!s.daily?'<button id="custom-open">Changer les thèmes</button>':''}<button data-page="errors">Revoir mes erreurs</button> <button data-page="home">Mon tableau de bord</button></div>`;return}const q=s.qs[s.index];content.innerHTML=`${returnButton}<button id="session-restart" style="float:right">Recommencer</button><p class="muted">${esc(s.title)}${s.custom||s.evaluation?' · '+esc(q.theme):''}</p><div class="row"><h1>À toi de jouer.</h1><span class="badge">Question ${s.index+1} / ${s.qs.length}</span></div>${s.evaluation?'':trainingOverview()}<div class="track"><div class="fill" style="width:${s.index/s.qs.length*100}%"></div></div><section class="card"><h2 class="question">${esc(q.text)}</h2><p class="note">Coche toutes les réponses correctes · 1 à 3 bonnes réponses.</p><div>${q.options.map((o,i)=>{const l=letters[i],yes=q.answers.includes(l),chosen=s.selected.includes(l),wrong=chosen!==yes;return `<label class="option ${s.graded?(wrong?'bad':yes?'good':''):''}"><input type="checkbox" value="${l}" ${chosen?'checked':''} ${s.graded?'disabled':''}><span><b>${l}.</b> ${esc(o)}${s.graded?`<span class="status">${wrong?(yes?'✕ Bonne réponse oubliée':'✕ Réponse cochée à tort'):yes?'✓ Bonne réponse':'✓ Réponse écartée correctement'}</span>`:''}</span></label>`}).join('')}</div><div id="result" aria-live="polite">${s.graded?`<div class="result ${(s.selected.length===q.answers.length&&q.answers.every(a=>s.selected.includes(a)))?'good':'bad'}"><h3>${(s.selected.length===q.answers.length&&q.answers.every(a=>s.selected.includes(a)))?'✓ Bonne réponse !':'✕ Réponse incorrecte'}</h3><p><strong>Corrigé : ${q.answers.join(', ')}</strong></p><p>${esc(q.explanation)}</p>${renderAnswerReview(q,s.selected)}</div>`:''}</div><button class="primary" id="validate">${s.graded?(s.index+1===s.qs.length?'Voir mon bilan':'Question suivante →'):'Valider les réponses'}</button></section>`}

const evaluationDefinitions=[{id:'2026-10-14',title:'Évaluation du 14/10',dateLabel:'14 octobre 2026',semester:1,ue:'B.1',courseIds:['b1-chimie','b1-cellule','b1-tissus','b1-anatomie','b1-systemes','b1-microbiologie','b1-precautions','b1-environnement']}];
function evaluationThemes(e){return themes.filter(t=>e.courseIds.includes(t.courseId))}
function evaluationQuestions(e,courseId='all'){return all.filter(q=>e.courseIds.includes(themes[q.ti].courseId)&&(courseId==='all'||themes[q.ti].courseId===courseId))}
function evaluationProgress(qs){const done=qs.filter(q=>records.has(q.id)).length,score=qs.filter(q=>records.get(q.id)?.correct).length;return {done,score}}
function renderEvaluations(){const selected=evaluationDefinitions.find(e=>e.id===evaluationId);if(!selected){content.innerHTML=`<p class="visual-kicker">MES ÉVALUATIONS</p><h1>Prépare ton prochain rendez-vous.</h1><p class="muted">Retrouve les QCM regroupés selon tes évaluations, avec une correction après chaque question.</p><div class="evaluation-list">${evaluationDefinitions.map(e=>{const qs=evaluationQuestions(e),progress=evaluationProgress(qs);return `<article class="card evaluation-card"><div class="evaluation-date"><strong>14</strong><span>OCTOBRE</span></div><div><span class="badge">Semestre ${e.semester} · UE ${e.ue}</span><h2>${esc(e.title)}</h2><p>${evaluationThemes(e).length} thèmes · ${qs.length} QCM corrigés</p><p class="note">${progress.done} questions déjà travaillées dans cet espace.</p><button class="primary" data-evaluation-open="${e.id}">Ouvrir l’évaluation →</button></div></article>`}).join('')}</div>`;return}
const qs=evaluationQuestions(selected),progress=evaluationProgress(qs);content.innerHTML=`<button class="back" data-page="evaluations">← Toutes les évaluations</button><header class="lesson-hero"><p class="visual-kicker">${esc(selected.dateLabel)} · SEMESTRE ${selected.semester} · UE ${selected.ue}</p><h1>${esc(selected.title)}</h1><p class="muted">Les QCM des huit thèmes à réviser, réunis ici. Choisis un thème ou lance l’ensemble en ordre mélangé.</p><div class="lesson-meta"><span>${qs.length} QCM</span><span>${evaluationThemes(selected).length} thèmes</span><span>À refaire autant de fois que tu veux</span></div></header><section class="card evaluation-launch"><h2>Tout le programme en une séance</h2><p>Cinq propositions par question, une à trois bonnes réponses. Coche toutes les bonnes réponses puis valide pour lire le corrigé.</p><button class="primary" data-evaluation-start="${selected.id}" data-evaluation-theme="all">Commencer / Reprendre les ${qs.length} QCM</button> <button data-evaluation-restart="${selected.id}" data-evaluation-theme="all">Recommencer</button><p class="note">${progress.done} / ${qs.length} déjà travaillés · ${progress.score} bonnes réponses lors des derniers essais. La progression des entraînements est partagée ; ta séance reprend automatiquement où tu t’es arrêté. Utilise « Recommencer » pour repartir de zéro.</p></section><h2 class="evaluation-themes-title">Ou révise un thème à la fois</h2><div class="program-grid">${selected.courseIds.map((id,i)=>{const t=evaluationThemes(selected).find(t=>t.courseId===id);if(!t)return '';const tqs=evaluationQuestions(selected,id),tp=evaluationProgress(tqs);return `<article class="card course-card program-card"><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><h3>${esc(t.title)}</h3><p class="course-card-meta">${tqs.length} QCM · ${tp.done} déjà travaillés</p><button class="primary" data-evaluation-start="${selected.id}" data-evaluation-theme="${id}">Commencer / Reprendre les ${tqs.length} QCM</button> <button data-evaluation-restart="${selected.id}" data-evaluation-theme="${id}">Recommencer</button></article>`}).join('')}</div>`}
function startEvaluation(id,courseId){const e=evaluationDefinitions.find(e=>e.id===id);if(!e||!(courseId==='all'||e.courseIds.includes(courseId)))return;const qs=evaluationQuestions(e,courseId);if(!qs.length)return;if(courseId==='all')for(let i=qs.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[qs[i],qs[j]]=[qs[j],qs[i]]}start(qs,e.title,false,'evaluation:'+id+':'+courseId);session.evaluation=id;session.evaluationTheme=courseId;page='evaluations';evaluationId=id;render();window.scrollTo(0,0)}

document.addEventListener('change',e=>{if(e.target.dataset?.courseChoice){const key=e.target.dataset.courseChoice,st=courseQuizState.get(key)||{selected:[]};if(st.graded)return;const n=Number(e.target.value);st.selected=e.target.checked?[...new Set([...st.selected,n])]:st.selected.filter(x=>x!==n);st.error=false;courseQuizState.set(key,st);saveCourseQuiz();return}if(e.target.id==='course-semester'){courseSemester=Number(e.target.value);customThemes.clear();revisionId=null;courseReadId=null;try{localStorage.setItem('ifsi-semester',String(courseSemester))}catch{}render();return}if(e.target.dataset?.customTheme!==undefined){const i=Number(e.target.dataset.customTheme);if(e.target.checked)customThemes.add(i);else customThemes.delete(i);customCount();return}if(session&&!session.graded&&e.target.matches('.option input')){session.selected=[...content.querySelectorAll('.option input:checked')].map(i=>i.value);if(!session.custom)drafts.set(session.qs[session.index].id,[...session.selected]);saveProgress();saveSession()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='daily-start'){startDaily()}else if(b.dataset.resumeSession){resumeSavedSession(b.dataset.resumeSession)}else if(b.dataset.progressUe){navigate('practice');courseSemester=Number(b.dataset.progressSemester);practiceDomain=b.dataset.progressUe.split('.')[0];practiceUE=b.dataset.progressUe;render();window.scrollTo(0,0)}else if(b.id==='backup-export'){downloadBackup()}else if(b.id==='backup-apply'){applyPendingBackup()}else if(b.dataset.evaluationRestart){startEvaluation(b.dataset.evaluationRestart,b.dataset.evaluationTheme||'all');restartSession()}else if(b.dataset.themeRestart!==undefined){const i=Number(b.dataset.themeRestart);start(all.filter(q=>q.ti===i),themes[i].title,true);restartSession()}else if(b.id==='session-restart'){restartSession()}else if(b.dataset.practiceDomain){page='practice';session=null;practiceDomain=b.dataset.practiceDomain;practiceUE=null;render();window.scrollTo(0,0)}else if(b.dataset.practiceUe){practiceUE=b.dataset.practiceUe;render();window.scrollTo(0,0)}else if(b.dataset.evaluationOpen){page='evaluations';session=null;evaluationId=b.dataset.evaluationOpen;render();window.scrollTo(0,0)}else if(b.dataset.evaluationStart){startEvaluation(b.dataset.evaluationStart,b.dataset.evaluationTheme||'all')}else if(b.dataset.trainingCourse){page='courses';session=null;courseUE=courseFiles.find(c=>c.id===b.dataset.trainingCourse)?.ue||'B.1';courseDomain=courseUE.split('.')[0];revisionId=null;courseReadId=b.dataset.trainingCourse;render();window.scrollTo(0,0)}else if(b.dataset.courseValidate){const id=b.dataset.courseValidate,i=Number(b.dataset.courseQuestion),key=id+'-'+i,q=courseQuizBank[id][i],st=courseQuizState.get(key)||{selected:[]};if(st.graded)return;if(!st.selected.length){st.error=true}else{st.graded=true;st.correct=st.selected.length===q.answers.length&&q.answers.every(n=>st.selected.includes(n));st.error=false}courseQuizState.set(key,st);if(st.graded){const qTraining=courseTrainingQuestion(id,i);if(qTraining){recordAnswer(qTraining,st.selected.map(n=>letters[n]),st.correct);saveProgress()}}saveCourseQuiz();const scrollY=window.scrollY||0;render();window.scrollTo(0,scrollY)}else if(b.dataset.courseReset){const id=b.dataset.courseReset;courseQuizBank[id].forEach((_,i)=>courseQuizState.delete(id+'-'+i));saveCourseQuiz();render();document.getElementById('qcm-'+id)?.scrollIntoView?.({block:'start'})}else if(b.dataset.readCourse){courseReadId=b.dataset.readCourse;revisionId=null;render();window.scrollTo(0,0)}else if(b.dataset.revision){courseReadId=null;revisionId=b.dataset.revision;render();window.scrollTo(0,0)}else if(b.dataset.domain){revisionId=null;courseReadId=null;page='courses';session=null;courseDomain=b.dataset.domain;courseUE=null;render();window.scrollTo(0,0)}else if(b.dataset.ue){revisionId=null;courseReadId=null;courseUE=b.dataset.ue;render();window.scrollTo(0,0)}else if(b.id==='custom-open'){session=null;page='practice';customPicker()}else if(b.id==='custom-toggle'){if(trainingThemes().every(({i})=>customThemes.has(i)))customThemes.clear();else trainingThemes().forEach(({i})=>customThemes.add(i));customPicker()}else if(b.id==='custom-restart'){customStart();if(session)restartSession()}else if(b.id==='custom-start'||b.id==='custom-again')customStart();else if(b.dataset.page)navigate(b.dataset.page);else if(b.dataset.theme!==undefined){const i=Number(b.dataset.theme);start(all.filter(q=>q.ti===i),themes[i].title,true)}else if(b.dataset.retry){start(b.dataset.retry==='all'?errors():all.filter(q=>q.id===Number(b.dataset.retry)),'Revoir mes erreurs')}else if(b.id==='validate'){if(session.graded){session.index++;if(session.resume)while(session.index<session.qs.length&&records.has(session.qs[session.index].id))session.index++;session.graded=false;session.selected=!session.custom&&session.index<session.qs.length?[...(drafts.get(session.qs[session.index].id)||[])]:[];quiz();window.scrollTo(0,0)}else if(!session.selected.length){document.getElementById('result').innerHTML='<p role="alert" class="error-title">Coche au moins une réponse avant de valider.</p>'}else{const q=session.qs[session.index];const ok=q.answers.length===session.selected.length&&q.answers.every(a=>session.selected.includes(a));recordAnswer(q,session.selected,ok);drafts.delete(q.id);saveProgress();session.score+=ok?1:0;session.graded=true;quiz()}}else if(b.id==='copy'){const t=document.getElementById('feedback');t.select();try{const ok=document.execCommand('copy');document.getElementById('copy-status').textContent=ok?' Remarques copiées.':' Sélectionne et copie le texte.'}catch{document.getElementById('copy-status').textContent=' Sélectionne et copie le texte.'}}});render();updateStorageStatus();

function courseVisual(id){
if(id==='cardiovasculaire')return '';
if(id==='concentration')return `<section class="card lesson-visual"><p class="visual-kicker">LA MASSE RESTE, LE VOLUME CHANGE</p><h2>Explore une dilution</h2><p>Les volumes sont supposés additifs. Modifie une donnée et observe le prélèvement nécessaire.</p><div class="formula-panel">C₁ × V₁ = C₂ × V₂</div><div class="calc-fields"><label>Concentration initiale (mg/mL)<input data-lesson-calc="dilution" id="dilution-c1" type="number" min="0.001" step="any" value="12"></label><label>Concentration finale (mg/mL)<input data-lesson-calc="dilution" id="dilution-c2" type="number" min="0.001" step="any" value="3"></label><label>Volume final (mL)<input data-lesson-calc="dilution" id="dilution-v2" type="number" min="0.001" step="any" value="40"></label></div><div id="dilution-result" class="calc-result" aria-live="polite"><strong>10 mL de solution initiale + 30 mL de solvant</strong><p>Volume final : 40 mL · Quantité de soluté : 120 mg.</p><div class="dilution-strip"><span style="width:25%">Solution</span><span style="width:75%">Solvant</span></div><p>V₁ = 3 × 40 / 12 = 10 mL ; solvant = 40 − 10 = 30 mL.</p></div></section><section class="card lesson-visual"><p class="visual-kicker">COMPRENDRE L’AUTONOMIE</p><h2>Le modèle d’une bouteille d’O₂</h2><p>Calcul pédagogique simplifié, à température constante. La réserve est une donnée choisie pour l’exercice.</p><div class="formula-panel">Durée ≈ capacité × (pression − réserve) ÷ débit</div><div class="calc-fields"><label>Capacité intérieure (L)<input data-lesson-calc="oxygen" id="oxygen-capacity" type="number" min="0.1" step="any" value="4"></label><label>Pression (bar)<input data-lesson-calc="oxygen" id="oxygen-pressure" type="number" min="0" step="any" value="150"></label><label>Débit (L/min)<input data-lesson-calc="oxygen" id="oxygen-flow" type="number" min="0.1" step="any" value="3"></label><label>Réserve de l’exercice (bar)<input data-lesson-calc="oxygen" id="oxygen-reserve" type="number" min="0" step="any" value="20"></label></div><div id="oxygen-result" class="calc-result" aria-live="polite"><strong>≈ 173,33 minutes avant la réserve</strong><p>4 × (150 − 20) = 520 L ; 520 / 3 ≈ 173,33 min.</p><p>Sans réserve : 200 min, soit 3 h 20 min.</p></div><p class="note">Pour un usage réel : tableaux et notice du fabricant, débit prescrit, marge adaptée au transfert et procédures du service. Cette estimation ne garantit pas l’autonomie réelle.</p></section>`;
if(id==='calculs-dose')return `<section class="card lesson-visual"><p class="visual-kicker">TROIS REPÈRES POUR DÉMARRER</p><h2>Unités → proportion → contrôle</h2><div class="conversion-grid"><div><strong>Masses</strong><p>1 g = 1 000 mg<br>1 mg = 1 000 µg</p></div><div><strong>Volumes</strong><p>1 L = 1 000 mL<br>1 cL = 10 mL</p></div><div><strong>Temps</strong><p>1 h = 60 min<br>1 h 30 = 1,5 h</p></div></div><div class="formula-panel">Quantité (mg) ÷ concentration (mg/mL) = volume (mL)</div><div class="worked-example"><p><strong>Exemple fictif :</strong> une solution contient 120 mg dans 6 mL. On cherche le volume correspondant à 70 mg.</p><ol><li>Concentration : 120 ÷ 6 = <strong>20 mg/mL</strong>.</li><li>Volume : 70 ÷ 20 = <strong>3,5 mL</strong>.</li><li>Contrôle : 3,5 × 20 = <strong>70 mg</strong>.</li></ol></div><h3>Pour un débit, choisis l’unité demandée</h3><div class="conversion-grid"><div><strong>mL/h</strong><p>Volume en mL ÷ durée en heures</p></div><div><strong>gouttes/min</strong><p>Volume en mL × facteur ÷ durée en minutes</p></div></div><p class="note">Le facteur de gouttes est celui du dispositif. Les exercices ne constituent pas des prescriptions.</p></section>`;
return '';
}
function updateLessonCalc(kind){const n=id=>{const raw=document.getElementById(id).value;return raw.trim()===''?NaN:Number(raw)},f=n=>Number(n.toFixed(2)).toLocaleString('fr-FR');
if(kind==='dilution'){const c1=n('dilution-c1'),c2=n('dilution-c2'),v2=n('dilution-v2'),out=document.getElementById('dilution-result');if(![c1,c2,v2].every(Number.isFinite)||c1<=0||c2<=0||v2<=0){out.innerHTML='<p>Saisis trois valeurs strictement positives.</p>';return}if(c2>c1){out.innerHTML='<p>Une dilution par ajout de solvant ne permet pas d’obtenir une concentration supérieure à celle de départ.</p>';return}const v1=c2*v2/c1,solvent=v2-v1,m=c2*v2;out.innerHTML=`<strong>${f(v1)} mL de solution initiale + ${f(solvent)} mL de solvant</strong><p>Volume final : ${f(v2)} mL · Quantité de soluté : ${f(m)} mg.</p><div class="dilution-strip" aria-label="Proportion du volume initial et du solvant ajouté"><span style="width:${v1/v2*100}%"></span><span style="width:${solvent/v2*100}%"></span></div><p>Part du volume : solution initiale ${f(v1/v2*100)} % ; solvant ${f(solvent/v2*100)} %.</p><p>V₁ = ${f(c2)} × ${f(v2)} / ${f(c1)} = ${f(v1)} mL ; solvant = ${f(v2)} − ${f(v1)} = ${f(solvent)} mL.</p>`}
if(kind==='oxygen'){const capacity=n('oxygen-capacity'),pressure=n('oxygen-pressure'),flow=n('oxygen-flow'),reserve=n('oxygen-reserve'),out=document.getElementById('oxygen-result');if(![capacity,pressure,flow,reserve].every(Number.isFinite)||capacity<=0||flow<=0||pressure<0||reserve<0){out.innerHTML='<p>Capacité et débit doivent être positifs ; pression et réserve ne peuvent pas être négatives.</p>';return}if(reserve>pressure){out.innerHTML='<p>La pression actuelle est inférieure à la réserve choisie : aucun volume n’est disponible avant ce seuil dans le modèle.</p>';return}const volume=capacity*(pressure-reserve),duration=volume/flow,gross=capacity*pressure/flow;out.innerHTML=`<strong>≈ ${f(duration)} minutes avant la réserve</strong><p>${f(capacity)} × (${f(pressure)} − ${f(reserve)}) = ${f(volume)} L ; ${f(volume)} / ${f(flow)} = ${f(duration)} min.</p><p>Sans réserve : ${f(gross)} min, soit ${Math.floor(gross/60)} h et ${f(gross%60)} min.</p>`}}
document.addEventListener('input',e=>{if(e.target.dataset?.lessonCalc)updateLessonCalc(e.target.dataset.lessonCalc)});

function normalizeSearch(value){return String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function searchMatches(name,query){const hay=normalizeSearch(name);return normalizeSearch(query).split(' ').filter(Boolean).every(word=>hay.includes(word))}
function clearSearch(){document.getElementById('site-search').value='';document.getElementById('search-results').hidden=true;document.getElementById('search-results').innerHTML='';document.getElementById('search-clear').hidden=true}
function renderSearch(){const input=document.getElementById('site-search'),out=document.getElementById('search-results'),query=input.value.trim();document.getElementById('search-clear').hidden=!query;if(!query){out.hidden=true;out.innerHTML='';return}const courses=courseFiles.filter(c=>searchMatches(c.title,query)),quizzes=themes.map((t,i)=>({t,i,...trainingMeta(t)})).filter(({t})=>searchMatches(t.title,query));out.hidden=false;out.innerHTML=`<p class="note" role="status">${courses.length} cours · ${quizzes.length} séries de QCM · Tous les semestres</p>${courses.length?`<h2>Cours</h2><div class="search-list">${courses.map(c=>`<button class="search-result" data-search-course="${c.id}"><span class="badge">Cours · S${c.semester} · UE ${c.ue}</span><strong>${esc(c.title)}</strong><span aria-hidden="true">→</span></button>`).join('')}</div>`:''}${quizzes.length?`<h2>QCM</h2><div class="search-list">${quizzes.map(({t,i,ue,semester})=>`<button class="search-result" data-search-theme="${i}"><span class="badge">QCM · S${semester} · UE ${ue}</span><strong>${esc(t.title)}</strong><small>${t.questions.length} questions corrigées</small><span aria-hidden="true">→</span></button>`).join('')}</div>`:''}${!courses.length&&!quizzes.length?'<p>Aucun résultat. Essaie un autre mot du titre, comme « cellule » ou « cœur ».</p>':''}`}
document.addEventListener('input',e=>{if(e.target.id==='site-search')renderSearch()});
document.addEventListener('keydown',e=>{if(e.target.id==='site-search'&&e.key==='Escape'){clearSearch()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='search-clear'){clearSearch();document.getElementById('site-search').focus();return}if(b.dataset.searchCourse){const c=courseFiles.find(c=>c.id===b.dataset.searchCourse);if(!c)return;clearSearch();navigate('courses');courseSemester=c.semester;try{localStorage.setItem('ifsi-semester',String(courseSemester))}catch{}courseDomain=c.ue.split('.')[0];courseUE=c.ue;courseReadId=c.id;render();window.scrollTo(0,0)}else if(b.dataset.searchTheme!==undefined){const i=Number(b.dataset.searchTheme),t=themes[i];if(!t)return;const meta=trainingMeta(t);clearSearch();navigate('practice');courseSemester=meta.semester;try{localStorage.setItem('ifsi-semester',String(courseSemester))}catch{}practiceDomain=meta.ue.split('.')[0];practiceUE=meta.ue;start(all.filter(q=>q.ti===i),t.title,true)}});

function localDay(date=new Date()){return new Intl.DateTimeFormat('fr-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}
function courseTrainingQuestion(id,index){const t=themes.find(t=>t.courseId===id);const q=courseQuizBank[id]?.[index];if(!t||!q)return null;return all.find(a=>themes[a.ti]===t&&a.text===q.text&&a.options.every((o,i)=>o===q.options[i]))||null}
function recordAnswer(q,selected,ok){const previous=reviewSchedule.get(q.id),streak=ok?Math.min((previous?.streak||0)+1,5):0,interval=ok?[1,3,7,14,30][streak-1]:1;const date=new Date();date.setDate(date.getDate()+interval);reviewSchedule.set(q.id,{due:localDay(date),streak,updatedAt:Date.now()});records.set(q.id,{correct:ok,selected:[...selected],updatedAt:Date.now()});const id=themes[q.ti]?.courseId;if(id){const i=courseQuizBank[id]?.findIndex(a=>a.text===q.text&&a.options.every((o,j)=>o===q.options[j]));if(i>=0){courseQuizState.set(id+'-'+i,{selected:selected.map(a=>letters.indexOf(a)),graded:true,correct:ok,updatedAt:Date.now()});saveCourseQuiz()}}try{localStorage.setItem('ifsi-review-v1',JSON.stringify([...reviewSchedule]))}catch{storageAvailable=false;updateStorageStatus()}}
function semesterQuestions(){return all.filter(q=>trainingMeta(themes[q.ti]).semester===courseSemester)}
function dailyQuestions(){const today=localDay(),scope=semesterQuestions();const rank=q=>records.get(q.id)?.correct===false?0:(reviewSchedule.get(q.id)?.due<=today||records.has(q.id)&&!reviewSchedule.has(q.id))?1:!records.has(q.id)?2:3;return scope.filter(q=>rank(q)<3).sort((a,b)=>rank(a)-rank(b)||(reviewSchedule.get(a.id)?.due||'').localeCompare(reviewSchedule.get(b.id)?.due||'')||a.id-b.id).slice(0,10)}
function startDaily(){const prefix='daily:'+localDay()+':S'+courseSemester;const existing=[...savedSessions].find(([key])=>key.startsWith(prefix+':'));if(existing){resumeSavedSession(existing[0]);return}const qs=dailyQuestions();if(!qs.length){navigate('home');return}start(qs,'Révisions du jour · '+new Date().toLocaleDateString('fr-FR'),false,prefix);session.custom=true;session.daily=true;quiz()}
function resumeSavedSession(key){const saved=savedSessions.get(key);if(!saved)return;const qs=saved.ids.map(id=>all.find(q=>q.id===id)).filter(Boolean);if(qs.length!==saved.ids.length)return;session={...saved,key,qs,selected:[...(saved.selected||[])]};page=session.evaluation?'evaluations':'practice';evaluationId=session.evaluation||null;const t=themes[qs[0]?.ti];if(t){const meta=trainingMeta(t);courseSemester=meta.semester;practiceDomain=meta.ue.split('.')[0];practiceUE=meta.ue}render();window.scrollTo(0,0)}
function ueStatistics(code,semester=courseSemester){const qs=all.filter(q=>{const m=trainingMeta(themes[q.ti]);return m.ue===code&&m.semester===semester}),done=qs.filter(q=>records.has(q.id)).length,right=qs.filter(q=>records.get(q.id)?.correct).length;return {total:qs.length,done,right,wrong:done-right,percent:qs.length?Math.round(done/qs.length*100):0,rate:done?Math.round(right/done*100):null}}
function progressCard(code,title){const st=ueStatistics(code),ts=trainingThemes(code);return `<article class="card ue-progress-card"><span class="badge">UE ${code}</span><h3>${esc(title)}</h3><p>${st.done} / ${st.total} QCM travaillés · ${st.percent} %</p><progress value="${st.done}" max="${Math.max(1,st.total)}" aria-label="Progression dans l’UE ${code}"></progress><div class="progress-metrics"><span>${st.rate===null?'—':st.rate+' %'} de réussite</span><span>${st.wrong} à revoir</span></div>${st.total?`<button data-progress-ue="${code}" data-progress-semester="${courseSemester}">Ouvrir les entraînements →</button><details class="recall"><summary>Voir les ${ts.length} chapitres</summary>${ts.map(({t})=>{const done=t.questions.filter(q=>records.has(q.id)).length,wrong=t.questions.filter(q=>records.get(q.id)?.correct===false).length;return `<p><strong>${esc(t.title)}</strong><br><span class="note">${done===0?'À commencer':done<t.questions.length?'En cours':wrong?'Terminé · à revoir':'Terminé · dernières réponses réussies'} · ${done} / ${t.questions.length} QCM${wrong?' · '+wrong+' erreurs':''}</span></p>`}).join('')}</details>`:'<p class="note">Aucun QCM disponible pour ce semestre.</p>'}</article>`}
function renderProgress(){content.innerHTML=semesterPicker()+`<p class="visual-kicker">MA PROGRESSION</p><h1>Vois où tu en es.</h1><p class="muted">La progression compte les questions travaillées. La réussite correspond à ta dernière réponse, sans garantir que la notion est définitivement acquise.</p>${courseDomains.map(d=>`<section class="progress-domain"><h2>Domaine ${d.id} · ${esc(d.name)}</h2><div class="progress-grid">${d.ues.map(([code,title])=>progressCard(code,title)).join('')}</div></section>`).join('')}`}
function renderDashboard(){const scope=semesterQuestions(),done=scope.filter(q=>records.has(q.id)).length,right=scope.filter(q=>records.get(q.id)?.correct).length,wrong=scope.filter(q=>records.get(q.id)?.correct===false).length,daily=dailyQuestions(),today=localDay();const latest=[...savedSessions].filter(([,s])=>s.index<s.ids.length&&s.ids.some(id=>scope.some(q=>q.id===id))).sort((a,b)=>(b[1].updatedAt||0)-(a[1].updatedAt||0))[0];const next=evaluationDefinitions.filter(e=>e.semester===courseSemester&&e.id>=today).sort((a,b)=>a.id.localeCompare(b.id))[0];const dailySaved=[...savedSessions].find(([key])=>key.startsWith('daily:'+today+':S'+courseSemester+':'));content.innerHTML=semesterPicker()+`<p class="visual-kicker">MON ESPACE DE RÉVISION</p><h1>Ta prochaine étape, ici.</h1><p class="muted">Reprends une séance, révise tes erreurs ou avance dans ton programme.</p><div class="dashboard-actions"><section class="hero daily-hero"><span class="badge">Une séance courte · jusqu’à 10 QCM</span><h2>À revoir aujourd’hui</h2><p>Les erreurs passent en premier, puis les questions à revoir et les notions que tu n’as pas encore travaillées.</p>${dailySaved?`<button data-resume-session="${esc(dailySaved[0])}">${dailySaved[1].index===dailySaved[1].ids.length?'Voir mon bilan du jour':'Reprendre mes révisions du jour'}</button>`:daily.length?'<button id="daily-start">Lancer mes révisions du jour →</button>':'<p>Tes révisions sont à jour pour ce semestre. Tu peux reprendre un chapitre dans Entraînement.</p>'}</section><section class="card continue-card"><span class="badge">Ta séance sauvegardée</span><h2>Continuer ma séance</h2>${latest?`<h3>${esc(latest[1].title)}</h3><p class="muted">Question ${Math.min(latest[1].index+1,latest[1].ids.length)} / ${latest[1].ids.length}${latest[1].graded?' · correction affichée':''}</p><button class="primary" data-resume-session="${esc(latest[0])}">Reprendre →</button>`:'<p class="muted">Commence un QCM : tu retrouveras ta séance ici.</p><button data-page="practice">Choisir une UE →</button>'}</section></div><div class="grid"><div class="card"><p class="muted">Questions travaillées · S${courseSemester}</p><div class="number">${done}<span class="note"> / ${scope.length}</span></div></div><div class="card"><p class="muted">Réussite actuelle</p><div class="number">${done?Math.round(right/done*100)+' %':'—'}</div><span class="note">Dernière réponse à chaque question</span></div><div class="card"><p class="muted">Questions à revoir</p><div class="number">${wrong}</div><button data-page="errors">Mon carnet d’erreurs →</button></div></div><section class="card row"><div><span class="badge">Prochaine évaluation</span><h2>${next?esc(next.title):'Pas d’évaluation à venir pour ce semestre'}</h2><p class="muted">${next?esc(next.dateLabel)+' · UE '+next.ue:'Tu peux toujours retrouver les évaluations existantes.'}</p></div><button ${next?'data-evaluation-open="'+next.id+'"':'data-page="evaluations"'}>Voir les QCM →</button></section><div class="row"><h2>Ta progression par UE</h2><button data-page="progress">Voir tous les domaines →</button></div><div class="progress-grid">${courseDomains.flatMap(d=>d.ues).filter(([code])=>trainingCount(code)>0).map(([code,title])=>progressCard(code,title)).join('')}</div><section class="card row"><div><h2>Garde une copie de ta progression</h2><p class="muted">Exporte tes réponses, séances et révisions pour les récupérer sur un autre appareil.</p></div><button data-page="backup">Ma sauvegarde →</button></section>`}
function renderAnswerReview(q,selected){const linked=courseFiles.find(c=>courseQuizBank[c.id]?.some(a=>a.text===q.text&&a.options.every((o,i)=>o===q.options[i])));const correct=q.answers.map(a=>typeof a==='number'?letters[a]:a);return `<details class="answer-review" open><summary>Ta correction, proposition par proposition</summary><div class="study-table-wrap"><table class="study-table"><thead><tr><th scope="col">Proposition</th><th scope="col">Attendu</th><th scope="col">Ton choix</th><th scope="col">Bilan</th></tr></thead><tbody>${q.options.map((o,i)=>{const letter=letters[i],yes=correct.includes(letter),chosen=selected.includes(letter);return `<tr><th scope="row">${letter}. ${esc(o)}</th><td>${yes?'Vraie · à cocher':'Fausse · à écarter'}</td><td>${chosen?'Cochée':'Non cochée'}</td><td>${yes===chosen?'✓ Correct':yes?'Bonne réponse oubliée':'Réponse cochée à tort'}</td></tr>`}).join('')}</tbody></table></div><p class="note">Relis l’explication ci-dessus pour comprendre les notions qui justifient le corrigé.</p>${linked?`<button data-training-course="${linked.id}">Relire le cours associé →</button>`:''}</details>`}
const BACKUP_KEYS=['ifsi-progress-v1','ifsi-sessions-v1','ifsi-course-qcm-v1','ifsi-review-v1','ifsi-custom-themes-v1','ifsi-semester'];
function createBackup(){saveProgress();if(session)saveSession();saveCourseQuiz();const data={};for(const key of BACKUP_KEYS){const raw=localStorage.getItem(key);if(raw!==null)data[key]=JSON.parse(raw)}return {format:'ifsi-revisions-backup',version:1,createdAt:new Date().toISOString(),data}}
function downloadBackup(){try{const backup=createBackup(),blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='revisions-ifsi-sauvegarde-'+localDay()+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);const status=document.getElementById('backup-status');if(status)status.textContent='Sauvegarde téléchargée. Conserve ce fichier pour restaurer ta progression.'}catch{document.getElementById('backup-status').textContent='Le téléchargement a échoué. Ta progression actuelle reste conservée.'}}
function validateBackup(value){const fail=()=>{throw new Error('Ce fichier de sauvegarde est invalide ou incompatible.')};if(!value||value.format!=='ifsi-revisions-backup'||value.version!==1||!value.data||typeof value.data!=='object'||Array.isArray(value.data))fail();const data=value.data,ids=new Set(all.map(q=>q.id)),courseKeys=new Map(courseFiles.flatMap(c=>courseQuizBank[c.id].map((q,i)=>[c.id+'-'+i,q])));const entries=(v)=>{if(!Array.isArray(v)||v.length>10000)fail();for(const e of v)if(!Array.isArray(e)||e.length!==2)fail();return v};const picks=(v,numeric=false)=>Array.isArray(v)&&v.length<=5&&new Set(v).size===v.length&&v.every(a=>numeric?Number.isInteger(a)&&a>=0&&a<5:letters.includes(a));for(const key of Object.keys(data))if(!BACKUP_KEYS.includes(key))fail();if(!data[STORAGE_KEY]||data[STORAGE_KEY].version!==1)fail();for(const [id,r] of entries(data[STORAGE_KEY].records)){if(!ids.has(id)||!r||typeof r.correct!=='boolean'||r.selected&&!picks(r.selected))fail()}for(const [id,v] of entries(data[STORAGE_KEY].drafts||[]))if(!ids.has(id)||!picks(v))fail();if(data['ifsi-sessions-v1'])for(const [key,s] of entries(data['ifsi-sessions-v1'])){if(typeof key!=='string'||key.length>10000||!s||typeof s.title!=='string'||!Array.isArray(s.ids)||!s.ids.length||s.ids.length>all.length||new Set(s.ids).size!==s.ids.length||!s.ids.every(id=>ids.has(id))||!Number.isInteger(s.index)||s.index<0||s.index>s.ids.length||!Number.isInteger(s.score)||s.score<0||s.score>s.ids.length||typeof s.graded!=='boolean'||!picks(s.selected))fail();if(s.evaluation&&!evaluationDefinitions.some(e=>e.id===s.evaluation&&(s.evaluationTheme==='all'||e.courseIds.includes(s.evaluationTheme))))fail()}
if(data['ifsi-course-qcm-v1'])for(const [key,st] of entries(data['ifsi-course-qcm-v1']))if(!courseKeys.has(key)||!st||!picks(st.selected,true)||st.graded!==undefined&&typeof st.graded!=='boolean'||st.correct!==undefined&&typeof st.correct!=='boolean')fail();if(data['ifsi-review-v1'])for(const [id,r] of entries(data['ifsi-review-v1']))if(!ids.has(id)||!r||!/^\d{4}-\d{2}-\d{2}$/.test(r.due)||!Number.isInteger(r.streak)||r.streak<0||r.streak>5)fail();if(data['ifsi-custom-themes-v1']&&(!Array.isArray(data['ifsi-custom-themes-v1'])||!data['ifsi-custom-themes-v1'].every(id=>ids.has(id))))fail();if(data['ifsi-semester']!==undefined&&(!Number.isInteger(data['ifsi-semester'])||data['ifsi-semester']<1||data['ifsi-semester']>6))fail();return value}
function renderBackup(){pendingBackup=null;content.innerHTML=`<p class="visual-kicker">MA SAUVEGARDE</p><h1>Ta progression reste avec toi.</h1><p class="muted">La sauvegarde contient tes réponses, tes QCM de fiches, tes séances en cours et tes révisions à venir. Elle ne contient pas les cours eux-mêmes.</p><div class="backup-grid"><section class="card"><h2>Exporter ma progression</h2><p>Télécharge un fichier de sauvegarde. Tu pourras l’ouvrir ici sur un autre appareil.</p><button class="primary" id="backup-export">Télécharger ma sauvegarde</button></section><section class="card"><h2>Restaurer une sauvegarde</h2><p>Choisis un fichier exporté depuis ce site. Un aperçu s’affichera avant la restauration.</p><label for="backup-file">Mon fichier de sauvegarde</label><input id="backup-file" type="file" accept=".json,application/json"><div id="backup-preview"></div></section></div><p id="backup-status" role="status" aria-live="polite"></p><p class="note">Une restauration remplace la progression de ce navigateur par celle du fichier. Exporte d’abord ta progression actuelle si tu souhaites la garder.</p>`}
async function readBackup(file){const out=document.getElementById('backup-preview');pendingBackup=null;if(!file)return;try{if(file.size>5000000)throw new Error('Le fichier est trop volumineux. Choisis une sauvegarde du site.');const value=validateBackup(JSON.parse(await file.text()));pendingBackup=value;const count=value.data[STORAGE_KEY].records.length,sessions=value.data['ifsi-sessions-v1']?.length||0;out.innerHTML=`<div class="result good"><strong>Sauvegarde compatible</strong><p>${count} questions travaillées · ${sessions} séances sauvegardées.</p><button class="primary" id="backup-apply">Restaurer cette sauvegarde</button></div>`}catch(error){out.innerHTML=`<p role="alert">${esc(error instanceof SyntaxError?'Ce fichier n’est pas une sauvegarde JSON valide.':error.message)}</p>`}}
function applyPendingBackup(){if(!pendingBackup)return;const old=BACKUP_KEYS.map(key=>[key,localStorage.getItem(key)]);try{for(const key of BACKUP_KEYS){const value=pendingBackup.data[key];if(value===undefined)localStorage.removeItem(key);else localStorage.setItem(key,JSON.stringify(value))}records.clear();drafts.clear();savedSessions.clear();courseQuizState.clear();reviewSchedule.clear();customThemes.clear();session=null;restoreProgress();for(const [key,st] of pendingBackup.data['ifsi-sessions-v1']||[])savedSessions.set(key,st);for(const [key,st] of pendingBackup.data['ifsi-course-qcm-v1']||[])courseQuizState.set(key,st);for(const [key,st] of pendingBackup.data['ifsi-review-v1']||[])reviewSchedule.set(key,st);for(const id of pendingBackup.data['ifsi-custom-themes-v1']||[]){const i=themes.findIndex(t=>t.questions[0]?.id===id);if(i>=0)customThemes.add(i)}courseSemester=pendingBackup.data['ifsi-semester']||1;navigate('backup');document.getElementById('backup-status').textContent='Sauvegarde restaurée. Tes séances sont disponibles sur le tableau de bord.'}catch{for(const [key,value] of old){try{if(value===null)localStorage.removeItem(key);else localStorage.setItem(key,value)}catch{}}document.getElementById('backup-status').textContent='Restauration impossible : espace de sauvegarde insuffisant. Le fichier n’a pas été appliqué.'}}
document.addEventListener('change',e=>{if(e.target.id==='backup-file')readBackup(e.target.files?.[0])});

function mergeCourseProgress(){for(const c of courseFiles)for(let i=0;i<courseQuizBank[c.id].length;i++){const st=courseQuizState.get(c.id+'-'+i),q=courseTrainingQuestion(c.id,i);if(q&&st?.graded&&(!records.has(q.id)||(st.updatedAt||0)>(records.get(q.id).updatedAt||0)))records.set(q.id,{correct:st.correct,selected:st.selected.map(n=>letters[n]),updatedAt:st.updatedAt||0})}}

function applyTheme(theme){if(!document.documentElement)return;document.documentElement.dataset.theme=theme;document.documentElement.style.colorScheme=theme;const button=document.getElementById('theme-toggle');if(button){const dark=theme==='dark';button.textContent=dark?'☀ Mode clair':'☾ Mode sombre';button.setAttribute('aria-pressed',String(dark));button.setAttribute('aria-label',dark?'Activer le mode clair':'Activer le mode sombre')}const meta=document.querySelector?.('meta[name="theme-color"]');meta?.setAttribute('content',theme==='dark'?'#0d1721':'#173e53')}
if(document.documentElement){applyTheme(document.documentElement.dataset.theme||'light');document.addEventListener('click',e=>{if(e.target.closest('button')?.id==='theme-toggle'){const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';applyTheme(theme);try{localStorage.setItem('ifsi-theme',theme)}catch{}}});const preference=window.matchMedia?.('(prefers-color-scheme: dark)');preference?.addEventListener?.('change',e=>{try{if(!localStorage.getItem('ifsi-theme'))applyTheme(e.matches?'dark':'light')}catch{}})}
